pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool shouldRevert) public {
        amount = bound(amount, 0, 1 ether);

        RevertibleReceiver rec = new RevertibleReceiver(shouldRevert);

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(rec), amount, "") {
            ok = true;
        } catch {
            ok = false;
        }

        if (shouldRevert && amount > 0) {
            assertTrue(ok);
        } else {
            assertTrue(ok);
        }
    }
}

contract RevertibleReceiver {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("reject");
    }
    fallback() external payable {
        if (shouldRevert) revert("reject");
    }
}
